<script setup lang="ts">
import RefreshButton from '@/components/RefreshButton.vue'
import { computed,ref } from 'vue'
import { useMutation,useQuery,useQueryClient } from '@tanstack/vue-query'
import { ElMessageBox } from 'element-plus';import { ElMessage } from '@/app/messages'
import { RouterLink } from 'vue-router'
import { decideAdminAiProposal,getAdminAiProposal,getAdminAiProposals,getAiTask,requestAdminAiInspection } from '@/api/ai'
import type { AdminAiProposal } from '@/api/ai'
import { readableError } from '@/api/errors'

const client=useQueryClient(),inspectionProblemNo=ref<number>(1),filterProblemNo=ref<number>(),status=ref('WAITING_REVIEW'),current=ref(1),selectedId=ref(''),inspectionTaskId=ref(''),note=ref('')
const proposals=useQuery({queryKey:computed(()=>['admin-ai-proposals',status.value,current.value,filterProblemNo.value]),queryFn:({signal})=>getAdminAiProposals({status:status.value,current:current.value,pageSize:20,problemNo:filterProblemNo.value},signal),refetchInterval:computed(()=>inspectionTaskId.value?2500:false)})
const detail=useQuery({queryKey:computed(()=>['admin-ai-proposal',selectedId.value]),queryFn:({signal})=>getAdminAiProposal(selectedId.value,signal),enabled:computed(()=>Boolean(selectedId.value))})
const inspection=useQuery({queryKey:computed(()=>['admin-ai-task',inspectionTaskId.value]),queryFn:({signal})=>getAiTask(inspectionTaskId.value,signal),enabled:computed(()=>Boolean(inspectionTaskId.value)),refetchInterval:q=>q.state.data&&['SUCCEEDED','FAILED','CANCELLED','WAITING_REVIEW'].includes(q.state.data.status)?false:2000})
const inspectMutation=useMutation({mutationFn:()=>{if(!inspectionProblemNo.value)throw new Error('请输入自然题号');return requestAdminAiInspection(inspectionProblemNo.value,crypto.randomUUID())},onSuccess:r=>{inspectionTaskId.value=r.taskId;ElMessage.success({ message: '已创建题目巡检任务' })},onError:e=>ElMessage.error({ message: readableError(e) })})
const decision=useMutation({mutationFn:(kind:'APPROVE'|'REJECT')=>decideAdminAiProposal(selectedId.value,{decision:kind,expectedProposalVersion:detail.data.value!.rowVersion,expectedLifecycleVersion:detail.data.value!.baseLifecycleVersion,note:note.value}),onSuccess:async r=>{if(r.status==='STALE')ElMessage.warning({ message: '题目基线已变化，建议过期且未创建草稿' });else ElMessage.success({ message: r.status==='APPROVED'?'已生成待复核的新版本草稿':'建议已拒绝' });await Promise.all([client.invalidateQueries({queryKey:['admin-ai-proposals']}),detail.refetch()])},onError:e=>ElMessage.error({ message: readableError(e) })})
const canDecide=computed(()=>detail.data.value?.status==='WAITING_REVIEW')
async function decide(kind:'APPROVE'|'REJECT'){if(!detail.data.value)return;const message=kind==='APPROVE'?'批准后会从当前版本创建一个未发布草稿，公开题目不会立即变化。':'拒绝这条题面修改建议？';try{await ElMessageBox.confirm(message,kind==='APPROVE'?'批准建议':'拒绝建议',{type:kind==='APPROVE'?'warning':'info'});decision.mutate(kind)}catch{return}}
function parseEvidence(value:AdminAiProposal['evidenceJson']){if(Array.isArray(value))return value;if(typeof value==='string'){try{return JSON.parse(value) as string[]}catch{return []}}return []}
</script>

<template>
  <div class="admin-ai">
    <header><div><p class="eyebrow">AI WORKFLOWS</p><h1>AI 巡检与维护建议</h1><p>Agent 只检查公开题面文字。建议经管理员批准后生成未发布草稿，仍需通过题库编辑与发布流程。</p></div><RefreshButton @click="proposals.refetch()" :loading="proposals.isFetching.value">刷新列表</RefreshButton></header>
    <el-alert title="题意、样例和判题正确性不由此巡检验证。建议标注为文字校对；公开版本只会在后续人工发布后变化。" type="warning" :closable="false" show-icon />
    <section class="panel inspection"><div><h2>发起巡检</h2><p>输入题库中的自然题号，巡检仅读取在线题目的标题、标签和公开题面。</p></div><el-input-number v-model="inspectionProblemNo" :min="1" :precision="0" placeholder="自然题号"/><el-button type="primary" :loading="inspectMutation.isPending.value" @click="inspectMutation.mutate()">开始巡检</el-button></section>
    <el-alert v-if="inspectionTaskId" :title="`巡检任务 ${inspectionTaskId}：${inspection.data.value?.status??'排队中'}${inspection.data.value?.message?' · '+inspection.data.value.message:''}`" :type="inspection.data.value?.status==='FAILED'?'error':'info'" show-icon/>
    <div class="filters"><el-select v-model="status"><el-option label="待审核" value="WAITING_REVIEW"/><el-option label="已批准" value="APPROVED"/><el-option label="已拒绝" value="REJECTED"/><el-option label="已过期" value="STALE"/><el-option label="全部" value="ALL"/></el-select><el-input-number v-model="filterProblemNo" :min="1" :precision="0" controls-position="right" placeholder="按题号筛选"/><el-button @click="current=1;proposals.refetch()">筛选</el-button></div>
    <div class="columns"><section class="panel list"><el-table v-loading="proposals.isLoading.value" :data="proposals.data.value?.records??[]" row-key="id" highlight-current-row @row-click="(row:AdminAiProposal)=>selectedId=row.id"><el-table-column prop="problemNo" label="题号" width="85"/><el-table-column prop="currentTitle" label="题目" min-width="150"/><el-table-column prop="baseProblemVersion" label="版本" width="80"/><el-table-column prop="status" label="状态" width="120"><template #default="scope"><el-tag :type="scope.row.status==='WAITING_REVIEW'?'warning':scope.row.status==='APPROVED'?'success':scope.row.status==='STALE'?'danger':'info'">{{scope.row.status}}</el-tag></template></el-table-column></el-table><div class="pager"><span>共 {{proposals.data.value?.total??0}} 条</span><el-pagination v-model:current-page="current" :page-size="20" :total="proposals.data.value?.total??0" layout="prev, pager, next"/></div></section>
      <section class="panel detail"><template v-if="detail.data.value"><div class="detail-title"><div><span class="eyebrow">题目 {{detail.data.value.problemNo}} · 基线 v{{detail.data.value.baseProblemVersion}}</span><h2>{{detail.data.value.proposalJson?.title??'维护建议'}}</h2></div><el-tag>{{detail.data.value.status}}</el-tag></div><p class="summary">{{detail.data.value.proposalJson?.summary}}</p><p class="muted">{{detail.data.value.diffMarkdown}}</p><h3>建议题面</h3><pre>{{detail.data.value.proposalJson?.content}}</pre><h3>模型依据</h3><ul><li v-for="(item,index) in parseEvidence(detail.data.value.evidenceJson)" :key="index">{{item}}</li></ul><p v-if="detail.data.value.proposalJson?.uncertainty" class="muted">不确定性：{{detail.data.value.proposalJson.uncertainty}}</p><p class="muted">{{JSON.stringify(detail.data.value.validationJson)}}</p><RouterLink v-if="detail.data.value.approvedDraftId" :to="`/admin/problems/${detail.data.value.approvedDraftId}/edit`">打开未发布草稿</RouterLink><div v-if="canDecide" class="decision"><el-input v-model="note" type="textarea" :rows="2" maxlength="1000" show-word-limit placeholder="审核备注（可选）"/><el-button type="danger" plain :loading="decision.isPending.value" @click="decide('REJECT')">拒绝</el-button><el-button type="primary" :loading="decision.isPending.value" @click="decide('APPROVE')">批准并创建草稿</el-button></div></template><el-empty v-else description="选择一条建议查看审核内容"/></section></div>
  </div>
</template>

<style scoped>
.admin-ai{padding:28px;max-width:1500px;margin:auto;color:var(--oj-text)}header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}h1{margin:4px 0 8px;font-size:26px}header p,.inspection p,.muted{color:var(--oj-text-muted);font-size:13px}.eyebrow{color:#8bb2ff;font-size:11px;letter-spacing:.12em}.panel{border:1px solid var(--oj-border);border-radius:10px;background:var(--oj-surface);padding:18px}.inspection{display:flex;align-items:center;gap:12px;margin:16px 0}.inspection div{flex:1}.inspection h2{margin:0 0 6px;font-size:16px}.inspection p{margin:0}.filters{display:flex;gap:10px;margin:18px 0}.filters .el-select{width:160px}.columns{display:grid;grid-template-columns:minmax(390px,1fr) minmax(400px,1fr);gap:16px}.list{min-width:0}.pager{display:flex;align-items:center;justify-content:space-between;margin-top:14px;color:var(--oj-text-muted);font-size:12px}.detail{min-height:420px}.detail-title{display:flex;align-items:center;justify-content:space-between}.detail h2{margin:6px 0 12px}.summary{font-weight:600}.detail h3{font-size:14px;margin:20px 0 8px}.detail pre{white-space:pre-wrap;max-height:360px;overflow:auto;background:#10151d;border:1px solid var(--oj-border);border-radius:8px;padding:12px;font:13px/1.6 ui-monospace,monospace}.detail ul{padding-left:20px;color:var(--oj-text-muted)}.decision{display:flex;align-items:flex-end;gap:8px;margin-top:20px}.decision .el-textarea{flex:1}@media(max-width:950px){.columns{grid-template-columns:1fr}.admin-ai{padding:16px}.inspection{flex-wrap:wrap}.inspection div{flex-basis:100%}}@media(max-width:560px){header{gap:10px}.filters{flex-wrap:wrap}.decision{align-items:stretch;flex-direction:column}}
</style>
